// Build task draft schema from Notion page.
const page = $input.item.json;
const props = page.properties || {};

function extractTitle(p) {
  for (const k in p) {
    const v = p[k];
    if (v && v.type === 'title' && Array.isArray(v.title)) {
      return v.title.map(t => t.plain_text).join('').trim();
    }
  }
  return '';
}

function extractRichTextDescription(p) {
  const frags = [];
  for (const k in p) {
    const v = p[k];
    if (v && v.type === 'rich_text' && Array.isArray(v.rich_text)) {
      const text = v.rich_text.map(t => t.plain_text).join('').trim();
      if (text) frags.push('**' + k + ':** ' + text);
    }
  }
  return frags.join('\n\n');
}

const title = extractTitle(props) || 'Untitled intake';
const description = extractRichTextDescription(props);
const url = page.url || '';
const id = page.id || '';

// Rough keyword-based type label inference.
const body = (title + ' ' + description).toLowerCase();
let typeLabel = 'Feature';
if (/\b(bug|broken|crash|error|fail|regression)\b/.test(body)) typeLabel = 'Bug';
else if (/\b(refactor|cleanup|chore|rename)\b/.test(body)) typeLabel = 'chore';
else if (/\b(design|mockup|visual|ui|ux)\b/.test(body)) typeLabel = 'design';
else if (/\b(research|investigate|compare|analy[sz]e|survey)\b/.test(body)) typeLabel = 'research';
else if (/\b(improve|enhance|upgrade|optimi[sz]e|polish)\b/.test(body)) typeLabel = 'Improvement';

// Priority inference (Linear numeric: 0=None, 1=Urgent, 2=High, 3=Medium, 4=Low).
let priorityInt = 3; // Medium as default (Normal)
if (/\b(urgent|asap|immediately|critical|blocker|blocking)\b/.test(body)) priorityInt = 1;
else if (/\b(high priority|important|soon)\b/.test(body)) priorityInt = 2;

return {
  json: {
    title: title,
    description: description,
    suggested_type_label: typeLabel,
    suggested_priority_int: priorityInt,
    linked_notion_page_id: id,
    linked_notion_page_url: url
  }
};

