// Dedupe check + resolve label/state IDs for downstream create.
const lookup = $input.item.json;
const draft = $('Build task draft').item.json;

function norm(t) {
  return (t || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const data = (lookup && lookup.data) || {};
const team = data.team || { states: { nodes: [] } };
const allLabels = (data.issueLabels && data.issueLabels.nodes) || [];
const existing = (data.issues && data.issues.nodes) || [];

const draftTitleNorm = norm(draft.title);
const match = existing.find(i => norm(i.title) === draftTitleNorm) || null;

const todoState = (team.states.nodes || []).find(s => s.type === 'unstarted') || null;

const labelIdByName = {};
for (const l of allLabels) labelIdByName[l.name] = l.id;

const labelIdsForCreate = [];
if (labelIdByName['intake-draft']) labelIdsForCreate.push(labelIdByName['intake-draft']);
if (labelIdByName[draft.suggested_type_label]) labelIdsForCreate.push(labelIdByName[draft.suggested_type_label]);

return {
  json: {
    match_found: !!match,
    matched_issue_id: match ? match.id : null,
    matched_issue_identifier: match ? match.identifier : null,
    matched_issue_url: match ? match.url : null,
    matched_issue_title: match ? match.title : null,
    todo_state_id: todoState ? todoState.id : null,
    label_ids_for_create: labelIdsForCreate,
    notion_backlink_failed_label_id: labelIdByName['notion-backlink-failed'] || null,
    title: draft.title,
    description: draft.description,
    suggested_type_label: draft.suggested_type_label,
    suggested_priority_int: draft.suggested_priority_int,
    linked_notion_page_id: draft.linked_notion_page_id,
    linked_notion_page_url: draft.linked_notion_page_url
  }
};

